(() => {
  function firstThreeDayAbsenceStreak(days) {
    if (!Array.isArray(days)) {
      throw new TypeError("days must be an array");
    }
    let count = 0;
    for (let i = 0; i < days.length; i++) {
      const entry = days[i];
      if (entry === null || typeof entry !== "object") {
        throw new TypeError("entry at index " + i + " must be an object");
      }
      const status = entry.status;
      if (status === "present") {
        count = 0;
      } else if (status === "absent") {
        count += 1;
        if (count === 3) {
          return entry.date;
        }
      } else {
        throw new Error("unknown status at index " + i + ": " + String(status));
      }
    }
    return null;
  }
  return { firstThreeDayAbsenceStreak };
})()

