build.unitScript:
const f = code.firstThreeDayAbsenceStreak;
const d = (date, status) => ({ date, status });
test("absent Thursday, Friday and next Monday returns Monday because the weekend does not break the streak", () => {
  const days = [d("2024-03-07", "absent"), d("2024-03-08", "absent"), d("2024-03-11", "absent")];
  assert.equal(f(days), "2024-03-11");
});
test("absent Thursday and Friday then present Monday returns null because the present day resets the count", () => {
  const days = [d("2024-03-07", "absent"), d("2024-03-08", "absent"), d("2024-03-11", "present")];
  assert.equal(f(days), null);
});
test("a fourth absence in the same streak still returns the date of the third absence", () => {
  const days = [d("2024-03-07", "absent"), d("2024-03-08", "absent"), d("2024-03-11", "absent"), d("2024-03-12", "absent")];
  assert.equal(f(days), "2024-03-11");
});
test("two separate runs of three absences returns the date the first run reached three", () => {
  const days = [
    d("2024-03-07", "absent"),
    d("2024-03-08", "absent"),
    d("2024-03-11", "absent"),
    d("2024-03-12", "present"),
    d("2024-03-13", "absent"),
    d("2024-03-14", "absent"),
    d("2024-03-15", "absent")
  ];
  assert.equal(f(days), "2024-03-11");
});
test("a holiday gap removed from the list does not break the streak", () => {
  const days = [d("2024-03-27", "absent"), d("2024-03-28", "absent"), d("2024-04-02", "absent")];
  assert.equal(f(days), "2024-04-02");
});
test("empty list and a list with no run of three absences both return null", () => {
  assert.equal(f([]), null);
  const days = [d("2024-03-07", "absent"), d("2024-03-08", "absent"), d("2024-03-11", "present"), d("2024-03-12", "absent"), d("2024-03-13", "absent")];
  assert.equal(f(days), null);
});

build.testScript:
test("a weekend gap does not reset an absence streak and the third day date is returned", function() {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});
test("a present day resets the count so two absences then a present day return nothing", function() {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});
test("a fourth absence in the same streak does not change the date already returned", function() {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});
test("only the first date any streak reached three is returned when a later streak also reaches three", function() {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "present" },
    { date: "2024-01-10", status: "absent" },
    { date: "2024-01-11", status: "absent" },
    { date: "2024-01-12", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-08");
});
test("an empty list returns nothing", function() {
  assert.equal(code.firstThreeDayAbsenceStreak([]), null);
});
test("two absences in a row never reach three so nothing is returned", function() {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});
test("a present day resets the count so earlier absences do not combine with later ones", function() {
  var days = [
    { date: "2024-01-04", status: "absent" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "present" },
    { date: "2024-01-09", status: "absent" },
    { date: "2024-01-10", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), null);
});
test("the count restarts after a present day and a weekend gap does not reset the new streak", function() {
  var days = [
    { date: "2024-01-04", status: "present" },
    { date: "2024-01-05", status: "absent" },
    { date: "2024-01-08", status: "absent" },
    { date: "2024-01-09", status: "absent" }
  ];
  assert.equal(code.firstThreeDayAbsenceStreak(days), "2024-01-09");
});

